create table if not exists public.student_progress_snapshots(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,snapshot_date date not null,reflection text not null default '' check(char_length(reflection)<=5000),metrics jsonb not null default '{}'::jsonb,highlights jsonb not null default '[]'::jsonb,priorities jsonb not null default '[]'::jsonb,created_at timestamptz not null default now(),unique(user_id,snapshot_date));
alter table public.student_progress_snapshots enable row level security;revoke all on public.student_progress_snapshots from anon;grant select,insert,update,delete on public.student_progress_snapshots to authenticated;
create policy "Students manage own progress snapshots" on public.student_progress_snapshots for all to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);
